type Transaction = { id: string; reference?: string; serviceType?: string; amountMinor?: number; retailPriceMinor?: number; status?: string; providerReference?: string; createdAt?: string | { seconds?: number } };
type SmsService = { id: string; name: string; priceMinor?: number; costMinor?: number };
type DataPlan = { id: string; name: string; costMinor: number };

const money = (minor = 0) => new Intl.NumberFormat("en-NG", { style: "currency", currency: "NGN" }).format(minor / 100);
const networks = [
  { id: "mtn", name: "MTN", logo: "/logos/mtn.png" }, { id: "airtel", name: "Airtel", logo: "/logos/airtel.png" },
  { id: "glo", name: "Glo", logo: "/logos/glo.png" }, { id: "9mobile", name: "9mobile", logo: "/logos/9mobile.png" },
] as const;
const countries = [
  { code: "NG", name: "Nigeria", dial: "+234", flag: "🇳🇬" }, { code: "US", name: "United States", dial: "+1", flag: "🇺🇸" },
  { code: "GB", name: "United Kingdom", dial: "+44", flag: "🇬🇧" }, { code: "CA", name: "Canada", dial: "+1", flag: "🇨🇦" },
  { code: "DE", name: "Germany", dial: "+49", flag: "🇩🇪" }, { code: "FR", name: "France", dial: "+33", flag: "🇫🇷" },
];
const discos = ["Ikeja Electric", "Eko Electric", "Abuja Electric", "Ibadan Electric", "Enugu Electric", "Port Harcourt Electric", "Kano Electric"];

function PageHeader({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: ReactNode }) {
  return <header className="workspace-heading"><div><p className="ui-eyebrow">{eyebrow}</p><h1>{title}</h1><p>{copy}</p></div>{action}</header>;
}

function StepRail({ current }: { current: number }) {
  const labels = ["Country", "Number", "Pricing", "Purchase", "Messages"];
  return <div className="step-rail">{labels.map((label, index) => <div key={label} className={`step-item ${index + 1 <= current ? "is-active" : ""}`}><span>{index + 1 < current ? <Check size={13} /> : index + 1}</span><b>{label}</b></div>)}</div>;
}

function EmptyState({ icon: Icon, title, copy, action }: { icon: typeof Inbox; title: string; copy: string; action?: ReactNode }) {
  return <div className="ui-empty"><span className="ui-empty-icon"><Icon size={22} /></span><h3 className="mt-4 text-sm font-black">{title}</h3><p className="mt-2 max-w-sm text-xs leading-5 text-[var(--muted)]">{copy}</p>{action && <div className="mt-5">{action}</div>}</div>;
}

function Status({ value = "pending" }: { value?: string }) {
  const status = value.toLowerCase();
  const cls = status === "successful" || status === "received" || status === "completed" ? "ui-badge-success" : status === "failed" || status === "cancelled" || status === "expired" ? "ui-badge-danger" : "ui-badge-warning";
  return <span className={`ui-badge ${cls}`}>{status === "successful" || status === "received" ? <BadgeCheck size={11} /> : status === "failed" ? <CircleAlert size={11} /> : <Clock3 size={11} />}{status.replaceAll("_", " ")}</span>;
}

function TransactionsTable({ kind }: { kind?: string }) {
  const [rows, setRows] = useState<Transaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  useEffect(() => { api<{ transactions: Transaction[] }>("/api/transactions").then(data => setRows(data.transactions)).catch(() => {}).finally(() => setLoading(false)); }, []);
  const filtered = rows.filter(row => !kind || kind === "all" || row.serviceType === kind).filter(row => `${row.reference || ""} ${row.serviceType || ""}`.toLowerCase().includes(query.toLowerCase()));
  return <section className="ui-card overflow-hidden"><div className="table-toolbar"><div><p className="ui-eyebrow">Ledger</p><h2>{kind && kind !== "all" ? `${kind} history` : "Transaction history"}</h2></div><div className="flex gap-2"><label className="table-search"><Search size={14} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search reference" /></label><button className="table-filter" aria-label="Filter transactions"><Filter size={15} /></button></div></div>{loading ? <div className="space-y-3 p-6">{[1, 2, 3].map(item => <div key={item} className="h-14 animate-pulse rounded-xl bg-[var(--surface-soft)]" />)}</div> : filtered.length ? <div className="overflow-x-auto"><table className="premium-table"><thead><tr><th>Reference</th><th>Service</th><th>Amount</th><th>Status</th><th>Provider reference</th></tr></thead><tbody>{filtered.map(row => <tr key={row.id}><td className="font-mono text-[10px]">{row.reference || row.id}</td><td className="font-extrabold capitalize">{row.serviceType?.replaceAll("_", " ") || "Wallet"}</td><td>{money(row.retailPriceMinor ?? row.amountMinor)}</td><td><Status value={row.status} /></td><td className="text-[var(--muted)]">{row.providerReference || "—"}</td></tr>)}</tbody></table></div> : <EmptyState icon={ReceiptText} title="No transactions found" copy="Real wallet and service transactions will appear here after they are created." />}</section>;
}

function NetworkPicker({ value, onChange }: { value: string; onChange: (network: string) => void }) {
  return <div className="network-grid">{networks.map(network => <button type="button" key={network.id} onClick={() => onChange(network.id)} className={`network-card ${value === network.id ? "is-selected" : ""}`}><span><Image src={network.logo} alt={`${network.name} logo`} width={44} height={44} /></span><b>{network.name}</b>{value === network.id && <Check size={14} />}</button>)}</div>;
}

function ConfirmModal({ title, children, busy, onClose, onConfirm }: { title: string; children: ReactNode; busy: boolean; onClose: () => void; onConfirm: () => void }) {
  return <div className="modal-layer"><button className="modal-backdrop" onClick={onClose} aria-label="Close confirmation" /><div className="modal-card"><div className="flex items-center justify-between"><div><p className="ui-eyebrow">Confirm purchase</p><h2 className="mt-2 text-xl font-black">{title}</h2></div><button onClick={onClose} className="table-filter"><X size={16} /></button></div><div className="modal-summary">{children}</div><div className="mt-5 grid grid-cols-2 gap-3"><button onClick={onClose} className="ui-button-secondary">Go back</button><button onClick={onConfirm} disabled={busy} className="ui-button-primary disabled:opacity-60">{busy ? <LoaderCircle className="animate-spin" size={16} /> : <ShieldCheck size={16} />} Confirm securely</button></div></div></div>;
}

function LegacySmsWorkspace() {
  const [search, setSearch] = useState(""); const [country, setCountry] = useState("NG"); const [services, setServices] = useState<SmsService[]>([]); const [selected, setSelected] = useState<SmsService | null>(null); const [loading, setLoading] = useState(false); const [buying, setBuying] = useState(false); const [order, setOrder] = useState<{ reference: string; number: string; status: string; expiresAt: string } | null>(null); const [messages, setMessages] = useState<Array<{ receivedAt: string; text: string }>>([]);
  const visibleCountries = countries.filter(item => item.name.toLowerCase().includes(search.toLowerCase()) || item.code.toLowerCase().includes(search.toLowerCase()));
  async function loadServices(code: string) { setCountry(code); setSelected(null); setLoading(true); try { const data = await api<{ services: SmsService[] }>(`/api/sms/services?country=${code}`); setServices(data.services); if (!data.services.length) toast.error("No supported services are currently available for this country."); } catch (error) { setServices([]); toast.error(error instanceof Error ? error.message : "Unable to load live services"); } finally { setLoading(false); } }
  async function purchase() { if (!selected) return; const price = selected.priceMinor ?? selected.costMinor; if (!price) { toast.error("Retail pricing is not configured for this service."); return; } setBuying(true); try { const result = await api<{ reference: string; number: string; status: string; expiresAt: string }>("/api/sms/orders", { method: "POST", body: JSON.stringify({ country, service: selected.id, priceMinor: price }) }); setOrder(result); toast.success("Number assigned successfully."); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to purchase number"); } finally { setBuying(false); } }
  async function refreshOrder() { if (!order) return; try { const data = await api<{ status: string; messages: Array<{ receivedAt: string; text: string }> }>(`/api/sms/orders/${order.reference}`); setOrder({ ...order, status: data.status }); setMessages(data.messages); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to refresh messages"); } }
  const step = order ? 5 : selected ? 4 : services.length ? 3 : country ? 2 : 1;
  return <><PageHeader eyebrow="Verification marketplace" title="SMS verification" copy="Choose a provider-supported destination and follow every stage of your rental in one clear flow." action={<Link href="/dashboard/transactions" className="ui-button-secondary"><History size={15} /> Rental history</Link>} /><StepRail current={step} /><div className="mt-5 grid items-start gap-5 xl:grid-cols-[1.15fr_.85fr]"><section className="ui-card p-5 sm:p-6"><div className="workspace-card-title"><span>01</span><div><h2>Select country</h2><p>Search available destinations.</p></div></div><label className="country-search"><Search size={15} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Search country" /></label><div className="country-grid">{visibleCountries.map(item => <button key={item.code} onClick={() => loadServices(item.code)} className={country === item.code ? "is-selected" : ""}><span>{item.flag}</span><div><b>{item.name}</b><small>{item.dial}</small></div>{country === item.code && <Check size={14} />}</button>)}</div><div className="workspace-divider" /><div className="workspace-card-title"><span>02</span><div><h2>Select service</h2><p>Availability and pricing are loaded live.</p></div></div>{loading ? <div className="service-skeleton-grid">{[1, 2, 3, 4].map(item => <div key={item} />)}</div> : services.length ? <div className="sms-service-grid">{services.map(service => <button key={service.id} onClick={() => setSelected(service)} className={selected?.id === service.id ? "is-selected" : ""}><span><MessageSquareText size={18} /></span><div><b>{service.name}</b><small>{service.priceMinor || service.costMinor ? money(service.priceMinor ?? service.costMinor) : "Price unavailable"}</small></div>{selected?.id === service.id && <Check size={14} />}</button>)}</div> : <EmptyState icon={Globe2} title="Choose a country to continue" copy="Only live provider-supported services will be shown. No availability is simulated." />}</section><aside className="space-y-5"><section className="verification-summary"><div className="flex items-center justify-between"><p className="ui-eyebrow text-[#ffb6c8]">Rental summary</p><Status value={order?.status || (selected ? "ready" : "pending")} /></div>{order ? <><div className="assigned-number"><small>Assigned number</small><div><b>{order.number}</b><button onClick={() => navigator.clipboard.writeText(order.number)}><Copy size={15} /></button></div><p>Reference: {order.reference}</p></div><button onClick={refreshOrder} className="verification-refresh"><LoaderCircle size={15} /> Refresh inbox</button><div className="sms-inbox">{messages.length ? messages.map((message, index) => <div key={`${message.receivedAt}-${index}`}><span><Inbox size={15} /></span><div><b>{message.text}</b><small>{message.receivedAt}</small></div></div>) : <EmptyState icon={Inbox} title="Waiting for SMS" copy="Real provider messages will appear here when received." />}</div></> : <><div className="summary-placeholder"><Smartphone size={26} /><h3>No number selected</h3><p>Select a country and service to review the live price before purchasing.</p></div><div className="summary-lines"><p><span>Country</span><b>{countries.find(item => item.code === country)?.name || "—"}</b></p><p><span>Service</span><b>{selected?.name || "—"}</b></p><p><span>Total</span><b>{selected?.priceMinor || selected?.costMinor ? money(selected.priceMinor ?? selected.costMinor) : "—"}</b></p></div><button disabled={!selected || buying} onClick={purchase} className="ui-button-primary mt-5 w-full disabled:cursor-not-allowed disabled:opacity-45">{buying ? <LoaderCircle className="animate-spin" size={16} /> : <KeyRound size={16} />} Purchase number</button></>}</section><div className="compliance-note"><ShieldCheck size={18} /><div><b>Permitted use only</b><p>Automated account creation, verification bypass, and unsupported services are prohibited.</p></div></div></aside></div></>;
}

type TelnyxNumberOffer = { id: string; phoneNumber: string; countryCode: string; phoneNumberType: string; features: string[]; retailPriceMinor: number; expiresAt: string };
type TelnyxOrder = { id?: string; reference: string; phoneNumber: string; countryCode?: string; status: string; retailPriceMinor?: number; providerReference?: string | null; createdAt?: string | null };
type InboundMessage = { id?: string; from?: string; text: string; receivedAt: string };

function TelnyxWorkspace() {
  const [countrySearch, setCountrySearch] = useState("");
  const [country, setCountry] = useState("NG");
  const [offers, setOffers] = useState<TelnyxNumberOffer[]>([]);
  const [selected, setSelected] = useState<TelnyxNumberOffer | null>(null);
  const [orders, setOrders] = useState<TelnyxOrder[]>([]);
  const [activeOrder, setActiveOrder] = useState<TelnyxOrder | null>(null);
  const [messages, setMessages] = useState<InboundMessage[]>([]);
  const [loading, setLoading] = useState(false);
  const [buying, setBuying] = useState(false);
  const visibleCountries = countries.filter((item) => item.name.toLowerCase().includes(countrySearch.toLowerCase()) || item.code.toLowerCase().includes(countrySearch.toLowerCase()));

  useEffect(() => { api<{ orders: TelnyxOrder[] }>("/api/sms/orders").then((data) => setOrders(data.orders)).catch(() => {}); }, []);

  async function searchNumbers(code = country) {
    setCountry(code); setSelected(null); setOffers([]); setLoading(true);
    try {
      const data = await api<{ numbers: TelnyxNumberOffer[] }>(`/api/sms/numbers?country=${code}&limit=20`);
      setOffers(data.numbers);
      if (!data.numbers.length) toast.error("Telnyx has no SMS-capable numbers available for this country right now.");
    } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to search Telnyx inventory"); }
    finally { setLoading(false); }
  }

  async function purchase() {
    if (!selected) return; setBuying(true);
    try {
      const result = await api<TelnyxOrder & { number: string }>("/api/sms/orders", { method: "POST", body: JSON.stringify({ offerId: selected.id, idempotencyKey: crypto.randomUUID() }) });
      const next = { ...result, phoneNumber: result.number, countryCode: country, retailPriceMinor: selected.retailPriceMinor };
      setActiveOrder(next); setOrders((current) => [next, ...current.filter((item) => item.reference !== next.reference)]); setSelected(null);
      toast.success(result.status === "active" ? "Number purchased and assigned." : "Number order submitted to Telnyx.");
    } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to purchase number"); }
    finally { setBuying(false); }
  }

  async function openOrder(order: TelnyxOrder) {
    setActiveOrder(order);
    try {
      const data = await api<{ reference: string; number: string; status: string; messages: InboundMessage[] }>(`/api/sms/orders/${order.reference}`);
      setActiveOrder({ ...order, phoneNumber: data.number, status: data.status }); setMessages(data.messages);
      setOrders((current) => current.map((item) => item.reference === order.reference ? { ...item, status: data.status } : item));
    } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to refresh this number"); }
  }

  const step = activeOrder ? 5 : selected ? 4 : offers.length ? 3 : 1;
  return <>
    <PageHeader eyebrow="Telnyx number marketplace" title="SMS virtual numbers" copy="Browse exact SMS-capable numbers from live Telnyx inventory, review the current price, and manage messages assigned to your account." action={<Link href="/dashboard/transactions" className="ui-button-secondary"><History size={15} /> Purchase history</Link>} />
    <StepRail current={step} />
    <div className="mt-5 grid items-start gap-5 xl:grid-cols-[1.15fr_.85fr]">
      <section className="ui-card p-5 sm:p-6">
        <div className="workspace-card-title"><span>01</span><div><h2>Choose a country</h2><p>Search live SMS-capable Telnyx inventory.</p></div></div>
        <label className="country-search"><Search size={15} /><input value={countrySearch} onChange={(event) => setCountrySearch(event.target.value)} placeholder="Search country" /></label>
        <div className="country-grid">{visibleCountries.map((item) => <button type="button" key={item.code} onClick={() => searchNumbers(item.code)} className={country === item.code ? "is-selected" : ""}><span>{item.flag}</span><div><b>{item.name}</b><small>{item.dial}</small></div>{country === item.code && <Check size={14} />}</button>)}</div>
        <div className="workspace-divider" />
        <div className="workspace-card-title"><span>02</span><div><h2>Select an exact number</h2><p>Results and prices expire after ten minutes.</p></div></div>
        {loading ? <div className="service-skeleton-grid">{[1, 2, 3, 4].map((item) => <div key={item} />)}</div> : offers.length ? <div className="sms-service-grid">{offers.map((offer) => <button type="button" key={offer.id} onClick={() => { setSelected(offer); setActiveOrder(null); }} className={selected?.id === offer.id ? "is-selected" : ""}><span><PhoneCall size={18} /></span><div><b>{offer.phoneNumber}</b><small>{money(offer.retailPriceMinor)} · SMS capable</small></div>{selected?.id === offer.id && <Check size={14} />}</button>)}</div> : <EmptyState icon={Globe2} title="Search live inventory" copy="Select a country above to see real SMS-capable numbers returned by Telnyx. No availability is simulated." action={<button type="button" onClick={() => searchNumbers()} className="ui-button-secondary"><Search size={15} /> Search {countries.find((item) => item.code === country)?.name}</button>} />}
      </section>
      <aside className="space-y-5">
        <section className="verification-summary">
          <div className="flex items-center justify-between"><p className="ui-eyebrow text-[#ffb6c8]">Number preview</p><Status value={activeOrder?.status || (selected ? "ready" : "pending")} /></div>
          {activeOrder ? <><div className="assigned-number"><small>Assigned number</small><div><b>{activeOrder.phoneNumber}</b><button onClick={() => navigator.clipboard.writeText(activeOrder.phoneNumber)} aria-label="Copy number"><Copy size={15} /></button></div><p>Reference: {activeOrder.reference}</p></div><button onClick={() => openOrder(activeOrder)} className="verification-refresh"><LoaderCircle size={15} /> Refresh status and inbox</button><div className="sms-inbox">{messages.length ? messages.map((message) => <div key={message.id || `${message.receivedAt}-${message.text}`}><span><Inbox size={15} /></span><div><b>{message.text}</b><small>{message.from || "Unknown sender"} · {new Date(message.receivedAt).toLocaleString()}</small></div></div>) : <EmptyState icon={Inbox} title="No messages received" copy="Only genuine inbound messages verified by the Telnyx webhook will appear here." />}</div></> : <><div className="summary-placeholder"><Smartphone size={26} /><h3>{selected ? selected.phoneNumber : "No number selected"}</h3><p>{selected ? "Review the server-calculated retail price before purchasing." : "Search a country and select an exact available number."}</p></div><div className="summary-lines"><p><span>Country</span><b>{countries.find((item) => item.code === country)?.name || "—"}</b></p><p><span>Number</span><b>{selected?.phoneNumber || "—"}</b></p><p><span>Total</span><b>{selected ? money(selected.retailPriceMinor) : "—"}</b></p></div><button disabled={!selected || buying} onClick={purchase} className="ui-button-primary mt-5 w-full disabled:cursor-not-allowed disabled:opacity-45">{buying ? <LoaderCircle className="animate-spin" size={16} /> : <KeyRound size={16} />} Purchase selected number</button></>}
        </section>
        <div className="compliance-note"><ShieldCheck size={18} /><div><b>Permitted use only</b><p>Use numbers only for lawful, provider-approved messaging. Verification bypass and automated account creation are prohibited.</p></div></div>
      </aside>
    </div>
    <section className="ui-card mt-5 overflow-hidden"><div className="table-toolbar"><div><p className="ui-eyebrow">My numbers</p><h2>Purchased-number management</h2></div><button type="button" onClick={() => api<{ orders: TelnyxOrder[] }>("/api/sms/orders").then((data) => setOrders(data.orders)).catch((error) => toast.error(error.message))} className="table-filter" aria-label="Refresh purchased numbers"><LoaderCircle size={15} /></button></div>{orders.length ? <div className="overflow-x-auto"><table className="premium-table"><thead><tr><th>Number</th><th>Country</th><th>Status</th><th>Price</th><th>Action</th></tr></thead><tbody>{orders.map((item) => <tr key={item.reference}><td className="font-extrabold">{item.phoneNumber}</td><td>{item.countryCode || "—"}</td><td><Status value={item.status} /></td><td>{money(item.retailPriceMinor)}</td><td><button type="button" onClick={() => openOrder(item)} className="ui-button-secondary">Open inbox <ChevronRight size={14} /></button></td></tr>)}</tbody></table></div> : <EmptyState icon={Smartphone} title="No purchased numbers" copy="Numbers successfully submitted from this marketplace will appear here." />}</section>
  </>;
}

type SmsPoolCountry = { id: number; name: string; shortName: string; region: string };
type SmsPoolService = { id: number; name: string };
type SmsPoolOffer = { id: string; poolId: number; poolName: string; stock: number; retailPriceMinor: number; expiresAt: string };
type SmsPoolRentalOffer = { id: string; rentalId: number; name: string; region: string; days: number; refundable: boolean; refundWithinHours: number; retailPriceMinor: number; expiresAt: string };
type SmsPoolOrder = { id?: string; reference: string; phoneNumber?: string | null; countryName?: string | null; serviceName?: string | null; name?: string; days?: number; status: string; retailPriceMinor?: number; expiresAt?: string | null };

function SmsPoolWorkspace() {
  const [mode, setMode] = useState<"one_time" | "rental">("one_time"); const [countriesList, setCountriesList] = useState<SmsPoolCountry[]>([]); const [country, setCountry] = useState<SmsPoolCountry | null>(null); const [services, setServices] = useState<SmsPoolService[]>([]); const [service, setService] = useState<SmsPoolService | null>(null); const [offers, setOffers] = useState<SmsPoolOffer[]>([]); const [selected, setSelected] = useState<SmsPoolOffer | null>(null); const [rentalOffers, setRentalOffers] = useState<SmsPoolRentalOffer[]>([]); const [selectedRental, setSelectedRental] = useState<SmsPoolRentalOffer | null>(null); const [orders, setOrders] = useState<SmsPoolOrder[]>([]); const [rentals, setRentals] = useState<SmsPoolOrder[]>([]); const [active, setActive] = useState<(SmsPoolOrder & { kind: "one_time" | "rental" }) | null>(null); const [messages, setMessages] = useState<InboundMessage[]>([]); const [loading, setLoading] = useState(false); const [buying, setBuying] = useState(false); const [query, setQuery] = useState(""); const [serviceQuery, setServiceQuery] = useState("");
  useEffect(() => { Promise.all([api<{ countries: SmsPoolCountry[] }>("/api/smspool/catalog").then((data) => setCountriesList(data.countries)), api<{ orders: SmsPoolOrder[] }>("/api/smspool/orders").then((data) => setOrders(data.orders)), api<{ rentals: SmsPoolOrder[] }>("/api/smspool/rentals").then((data) => setRentals(data.rentals))]).catch((error) => toast.error(error instanceof Error ? error.message : "Unable to load SMSPool")); }, []);
  useEffect(() => { if (mode !== "rental" || rentalOffers.length) return; setLoading(true); api<{ offers: SmsPoolRentalOffer[] }>("/api/smspool/rentals/catalog").then((data) => setRentalOffers(data.offers)).catch((error) => toast.error(error.message)).finally(() => setLoading(false)); }, [mode, rentalOffers.length]);
  async function chooseCountry(item: SmsPoolCountry) { setCountry(item); setService(null); setOffers([]); setSelected(null); setLoading(true); try { const data = await api<{ services: SmsPoolService[] }>(`/api/smspool/catalog?country=${item.id}`); setServices(data.services); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to load services"); } finally { setLoading(false); } }
  async function chooseService(item: SmsPoolService) { if (!country) return; setService(item); setSelected(null); setLoading(true); try { const data = await api<{ offers: SmsPoolOffer[]; exactNumberSelectionSupported: boolean }>(`/api/smspool/offers?country=${country.id}&service=${item.id}`); setOffers(data.offers); if (!data.offers.length) toast.error("No SMSPool stock is available for this selection."); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to load pricing"); } finally { setLoading(false); } }
  async function purchase() { const offerId = mode === "rental" ? selectedRental?.id : selected?.id; if (!offerId) return; setBuying(true); try { const path = mode === "rental" ? "/api/smspool/rentals" : "/api/smspool/orders"; const result = await api<{ reference: string; number?: string | null; status: string; expiresAt?: string }>(path, { method: "POST", body: JSON.stringify({ offerId, idempotencyKey: crypto.randomUUID() }) }); const next: SmsPoolOrder = { reference: result.reference, phoneNumber: result.number, status: result.status, retailPriceMinor: mode === "rental" ? selectedRental?.retailPriceMinor : selected?.retailPriceMinor, expiresAt: result.expiresAt, ...(mode === "rental" ? { name: selectedRental?.name, days: selectedRental?.days } : { countryName: country?.name, serviceName: service?.name }) }; if (mode === "rental") setRentals((rows) => [next, ...rows]); else setOrders((rows) => [next, ...rows]); setActive({ ...next, kind: mode }); toast.success("SMSPool order submitted."); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to purchase"); } finally { setBuying(false); } }
  async function refresh(item: SmsPoolOrder, kind: "one_time" | "rental") { try { const path = kind === "rental" ? `/api/smspool/rentals/${item.reference}` : `/api/smspool/orders/${item.reference}`; const data = await api<{ number?: string | null; status: string; expiresAt?: string | null; messages: InboundMessage[] }>(path); setActive({ ...item, phoneNumber: data.number, status: data.status, expiresAt: data.expiresAt, kind }); setMessages(data.messages); const setter = kind === "rental" ? setRentals : setOrders; setter((rows) => rows.map((row) => row.reference === item.reference ? { ...row, phoneNumber: data.number, status: data.status, expiresAt: data.expiresAt } : row)); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to refresh order"); } }
  const filteredCountries = countriesList.filter((item) => `${item.name} ${item.shortName}`.toLowerCase().includes(query.toLowerCase())); const filteredServices = services.filter((item) => item.name.toLowerCase().includes(serviceQuery.toLowerCase())); const currentOffer = mode === "rental" ? selectedRental : selected; const rows = [...orders.map((item) => ({ ...item, kind: "one_time" as const })), ...rentals.map((item) => ({ ...item, kind: "rental" as const }))];
  return <><PageHeader eyebrow="Alternative SMS provider" title="SMSPool verification" copy="Browse live country, service, stock and price data. SMSPool assigns the phone number only after a successful order." action={<Link href="/dashboard/transactions" className="ui-button-secondary"><History size={15} /> Purchase history</Link>} /><div className="amount-options mt-5 max-w-md"><button type="button" className={mode === "one_time" ? "is-selected" : ""} onClick={() => { setMode("one_time"); setActive(null); }}>One-time SMS</button><button type="button" className={mode === "rental" ? "is-selected" : ""} onClick={() => { setMode("rental"); setActive(null); }}>Rentals</button></div><div className="mt-5 grid items-start gap-5 xl:grid-cols-[1.15fr_.85fr]"><section className="ui-card p-5 sm:p-6">{mode === "one_time" ? <><div className="workspace-card-title"><span>01</span><div><h2>Country and service</h2><p>Loaded directly from SMSPool.</p></div></div><label className="country-search"><Search size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search country" /></label><div className="country-grid">{filteredCountries.slice(0, 12).map((item) => <button type="button" key={item.id} onClick={() => chooseCountry(item)} className={country?.id === item.id ? "is-selected" : ""}><span>{item.shortName}</span><div><b>{item.name}</b><small>{item.region}</small></div>{country?.id === item.id && <Check size={14} />}</button>)}</div>{country && <><div className="workspace-divider" /><div className="workspace-card-title"><span>02</span><div><h2>Select service</h2><p>Choose the permitted destination service.</p></div></div><label className="country-search"><Search size={15} /><input value={serviceQuery} onChange={(event) => setServiceQuery(event.target.value)} placeholder="Search all services" /></label><div className="sms-service-grid">{filteredServices.slice(0, 60).map((item) => <button type="button" key={item.id} onClick={() => chooseService(item)} className={service?.id === item.id ? "is-selected" : ""}><span><MessageSquareText size={18} /></span><div><b>{item.name}</b><small>Service ID {item.id}</small></div>{service?.id === item.id && <Check size={14} />}</button>)}</div></>}{service && <><div className="workspace-divider" /><div className="workspace-card-title"><span>03</span><div><h2>Availability and price</h2><p>Select an available provider pool.</p></div></div>{loading ? <div className="service-skeleton-grid"><div /><div /></div> : <div className="sms-service-grid">{offers.map((offer) => <button type="button" key={offer.id} onClick={() => setSelected(offer)} className={selected?.id === offer.id ? "is-selected" : ""}><span><Globe2 size={18} /></span><div><b>{offer.poolName}</b><small>{money(offer.retailPriceMinor)} · {offer.stock > 0 ? `${offer.stock} available` : "Live stock"}</small></div>{selected?.id === offer.id && <Check size={14} />}</button>)}</div>}</>}</> : <><div className="workspace-card-title"><span>01</span><div><h2>Choose rental duration</h2><p>Live rental products and refund eligibility from SMSPool.</p></div></div>{loading ? <div className="service-skeleton-grid"><div /><div /><div /></div> : <div className="sms-service-grid">{rentalOffers.map((offer) => <button type="button" key={offer.id} onClick={() => setSelectedRental(offer)} className={selectedRental?.id === offer.id ? "is-selected" : ""}><span><Clock3 size={18} /></span><div><b>{offer.name} · {offer.days} days</b><small>{money(offer.retailPriceMinor)} · {offer.refundable ? `Refundable within ${offer.refundWithinHours}h under provider rules` : "Non-refundable"}</small></div>{selectedRental?.id === offer.id && <Check size={14} />}</button>)}</div>}</>}</section><aside className="space-y-5"><section className="verification-summary"><div className="flex items-center justify-between"><p className="ui-eyebrow text-[#ffb6c8]">Order summary</p><Status value={active?.status || (currentOffer ? "ready" : "pending")} /></div>{active ? <><div className="assigned-number"><small>{active.phoneNumber ? "Assigned number" : "Awaiting assignment"}</small><div><b>{active.phoneNumber || "Pending provider"}</b>{active.phoneNumber && <button onClick={() => navigator.clipboard.writeText(active.phoneNumber!)}><Copy size={15} /></button>}</div><p>Reference: {active.reference}</p></div><button onClick={() => refresh(active, active.kind)} className="verification-refresh"><LoaderCircle size={15} /> Refresh status and inbox</button><div className="sms-inbox">{messages.length ? messages.map((message) => <div key={message.id || `${message.receivedAt}-${message.text}`}><span><Inbox size={15} /></span><div><b>{message.text}</b><small>{message.from || "SMSPool"} · {message.receivedAt}</small></div></div>) : <EmptyState icon={Inbox} title="Waiting for SMS" copy="Only real messages returned by SMSPool will appear here." />}</div></> : <><div className="summary-placeholder"><Smartphone size={26} /><h3>Number assigned after purchase</h3><p>SMSPool does not provide a browsable exact-number inventory. Your number is returned only when the provider accepts the order.</p></div><div className="summary-lines"><p><span>Product</span><b>{mode === "rental" ? selectedRental ? `${selectedRental.name} · ${selectedRental.days} days` : "—" : service?.name || "—"}</b></p><p><span>Availability</span><b>{mode === "rental" ? selectedRental ? "Live rental" : "—" : selected ? selected.stock > 0 ? `${selected.stock} in stock` : "Live" : "—"}</b></p><p><span>Total</span><b>{currentOffer ? money(currentOffer.retailPriceMinor) : "—"}</b></p></div><button disabled={!currentOffer || buying} onClick={purchase} className="ui-button-primary mt-5 w-full disabled:cursor-not-allowed disabled:opacity-45">{buying ? <LoaderCircle className="animate-spin" size={16} /> : <KeyRound size={16} />} Purchase through SMSPool</button></>}</section><div className="compliance-note"><ShieldCheck size={18} /><div><b>Provider restrictions apply</b><p>Use only for lawful, provider-permitted verification. Exact-number selection is not presented because SMSPool does not publish exact inventory.</p></div></div></aside></div><section className="ui-card mt-5 overflow-hidden"><div className="table-toolbar"><div><p className="ui-eyebrow">SMSPool activity</p><h2>Orders and rentals</h2></div></div>{rows.length ? <div className="overflow-x-auto"><table className="premium-table"><thead><tr><th>Number / product</th><th>Type</th><th>Status</th><th>Price</th><th>Action</th></tr></thead><tbody>{rows.map((item) => <tr key={item.reference}><td className="font-extrabold">{item.phoneNumber || item.serviceName || item.name || "Awaiting assignment"}</td><td>{item.kind === "rental" ? "Rental" : "One-time SMS"}</td><td><Status value={item.status} /></td><td>{money(item.retailPriceMinor)}</td><td><button type="button" onClick={() => refresh(item, item.kind)} className="ui-button-secondary">Manage <ChevronRight size={14} /></button></td></tr>)}</tbody></table></div> : <EmptyState icon={Smartphone} title="No SMSPool orders" copy="Real orders will appear here after testing is completed and purchases are enabled." />}</section></>;
}

function SmsWorkspace() { const [provider, setProvider] = useState<"telnyx" | "smspool">("telnyx"); return <><div className="amount-options mb-5 max-w-md"><button type="button" className={provider === "telnyx" ? "is-selected" : ""} onClick={() => setProvider("telnyx")}>Telnyx</button><button type="button" className={provider === "smspool" ? "is-selected" : ""} onClick={() => setProvider("smspool")}>SMSPool</button></div>{provider === "telnyx" ? <TelnyxWorkspace /> : <SmsPoolWorkspace />}</>; }

function VtuWorkspace({ type }: { type: "airtime" | "data" | "electricity" }) {
  const [network, setNetwork] = useState("mtn"); const [phone, setPhone] = useState(""); const [amount, setAmount] = useState(""); const [plans, setPlans] = useState<DataPlan[]>([]); const [plan, setPlan] = useState<DataPlan | null>(null); const [provider, setProvider] = useState(discos[0]); const [meterType, setMeterType] = useState("prepaid"); const [meterNumber, setMeterNumber] = useState(""); const [meterName, setMeterName] = useState(""); const [loading, setLoading] = useState(false); const [confirm, setConfirm] = useState(false);
  useEffect(() => { if (type !== "data") return; setPlan(null); setPlans([]); api<{ plans: DataPlan[] }>(`/api/data/plans?network=${network}`).then(data => setPlans(data.plans)).catch(error => toast.error(error instanceof Error ? error.message : "Unable to load live plans")); }, [network, type]);
  async function validateMeter() { setLoading(true); try { const result = await api<{ customerName: string }>("/api/orders/electricity/validate", { method: "POST", body: JSON.stringify({ provider, meterType, meterNumber }) }); setMeterName(result.customerName); toast.success("Meter details verified."); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to validate meter"); } finally { setLoading(false); } }
  function review(event: FormEvent) { event.preventDefault(); if (type === "data" && !plan) { toast.error("Select a data bundle first."); return; } if (type === "electricity" && !meterName) { toast.error("Validate the meter before payment."); return; } setConfirm(true); }
  async function purchase() { const amountMinor = type === "data" ? plan?.costMinor || 0 : Math.round(Number(amount) * 100); setLoading(true); try { const body = type === "electricity" ? { provider, meterType, meterNumber, amountMinor } : { network, phone: phone.replace(/\s/g, ""), ...(type === "data" ? { planId: plan?.id } : {}), amountMinor }; const result = await api<{ reference: string; status: string; token?: string }>(`/api/orders/${type}`, { method: "POST", body: JSON.stringify(body) }); setConfirm(false); toast[result.status === "failed" ? "error" : "success"](`Transaction ${result.status}. Reference: ${result.reference}${result.token ? ` Token: ${result.token}` : ""}`); } catch (error) { toast.error(error instanceof Error ? error.message : "Transaction could not be completed"); } finally { setLoading(false); } }
  const title = type === "airtime" ? "Buy airtime" : type === "data" ? "Buy mobile data" : "Pay electricity bill";
  const copy = type === "airtime" ? "Recharge any supported Nigerian network in a few clear steps." : type === "data" ? "Select from live bundles returned by your configured provider." : "Validate the meter owner before making a secure payment.";
  return <><PageHeader eyebrow="Digital services" title={title} copy={copy} action={<Link href="/dashboard/transactions" className="ui-button-secondary"><History size={15} /> View history</Link>} /><form onSubmit={review} className="purchase-layout"><section className="ui-card p-5 sm:p-7">{type !== "electricity" ? <><div className="workspace-card-title"><span>01</span><div><h2>Choose network</h2><p>Select the recipient&apos;s mobile network.</p></div></div><NetworkPicker value={network} onChange={setNetwork} /><div className="workspace-divider" /><div className="workspace-card-title"><span>02</span><div><h2>{type === "data" ? "Choose a bundle" : "Enter recharge details"}</h2><p>We&apos;ll confirm everything before payment.</p></div></div>{type === "data" ? plans.length ? <div className="plan-grid">{plans.map(item => <button type="button" key={item.id} onClick={() => setPlan(item)} className={plan?.id === item.id ? "is-selected" : ""}><Wifi size={17} /><div><b>{item.name}</b><small>{money(item.costMinor)}</small></div>{plan?.id === item.id && <Check size={14} />}</button>)}</div> : <EmptyState icon={Wifi} title="No live bundles loaded" copy="Configure the VTU provider to retrieve real data plans." /> : <div className="amount-options">{[500, 1000, 2000, 5000].map(value => <button type="button" onClick={() => setAmount(String(value))} className={amount === String(value) ? "is-selected" : ""} key={value}>₦{value.toLocaleString()}</button>)}</div>}<div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="ui-label">Phone number<input required value={phone} onChange={event => setPhone(event.target.value)} className="ui-input" inputMode="tel" placeholder="080 0000 0000" /></label>{type === "airtime" && <label className="ui-label">Custom amount<div className="relative"><span className="input-prefix">₦</span><input required min="100" type="number" value={amount} onChange={event => setAmount(event.target.value)} className="ui-input pl-8" placeholder="0.00" /></div></label>}</div></> : <><div className="workspace-card-title"><span>01</span><div><h2>Electricity provider</h2><p>Choose your distribution company.</p></div></div><div className="grid gap-4 sm:grid-cols-2"><label className="ui-label">Distribution company<select value={provider} onChange={event => { setProvider(event.target.value); setMeterName(""); }} className="ui-input">{discos.map(item => <option key={item}>{item}</option>)}</select></label><label className="ui-label">Meter type<select value={meterType} onChange={event => { setMeterType(event.target.value); setMeterName(""); }} className="ui-input"><option value="prepaid">Prepaid meter</option><option value="postpaid">Postpaid meter</option></select></label></div><div className="workspace-divider" /><div className="workspace-card-title"><span>02</span><div><h2>Validate meter</h2><p>Confirm the customer before payment.</p></div></div><div className="grid gap-4 sm:grid-cols-[1fr_auto]"><label className="ui-label">Meter number<input required value={meterNumber} onChange={event => { setMeterNumber(event.target.value); setMeterName(""); }} className="ui-input" inputMode="numeric" placeholder="Enter meter number" /></label><button type="button" onClick={validateMeter} disabled={loading || meterNumber.length < 5} className="ui-button-secondary self-end disabled:opacity-50">{loading ? <LoaderCircle className="animate-spin" size={15} /> : <ShieldCheck size={15} />} Validate meter</button></div>{meterName && <div className="verified-customer"><BadgeCheck size={18} /><div><small>Verified customer</small><b>{meterName}</b></div></div>}<label className="ui-label mt-5">Payment amount<div className="relative"><span className="input-prefix">₦</span><input required min="100" type="number" value={amount} onChange={event => setAmount(event.target.value)} className="ui-input pl-8" placeholder="0.00" /></div></label></>}<button className="ui-button-primary mt-7 w-full">Review purchase <ArrowRight size={15} /></button></section><aside className="purchase-aside"><div className="purchase-aside-icon">{type === "airtime" ? <PhoneCall /> : type === "data" ? <Wifi /> : <Zap />}</div><p className="ui-eyebrow text-[#ffb6c8]">Order summary</p><h2>{title}</h2><div className="purchase-summary-lines"><p><span>{type === "electricity" ? "Provider" : "Network"}</span><b className="capitalize">{type === "electricity" ? provider : network}</b></p><p><span>{type === "electricity" ? "Meter" : "Recipient"}</span><b>{type === "electricity" ? meterNumber || "—" : phone || "—"}</b></p>{type === "data" && <p><span>Plan</span><b>{plan?.name || "—"}</b></p>}<p><span>Total</span><b>{type === "data" ? plan ? money(plan.costMinor) : "—" : amount ? `₦${Number(amount).toLocaleString()}` : "—"}</b></p></div><div className="purchase-safety"><ShieldCheck size={16} /><p>Prices and balance are revalidated securely on the server.</p></div></aside></form>{confirm && <ConfirmModal title={title} busy={loading} onClose={() => setConfirm(false)} onConfirm={purchase}><p><span>Service</span><b>{title}</b></p><p><span>Recipient</span><b>{type === "electricity" ? meterNumber : phone}</b></p><p><span>Amount</span><b>{type === "data" ? money(plan?.costMinor) : `₦${Number(amount).toLocaleString()}`}</b></p></ConfirmModal>}</>;
}

function WalletWorkspace() {
  const [balance, setBalance] = useState(0); const [amount, setAmount] = useState(""); const [loading, setLoading] = useState(false);
  useEffect(() => { api<{ balanceMinor: number }>("/api/wallet").then(data => setBalance(data.balanceMinor)).catch(() => {}); }, []);
  async function fund(event: FormEvent) { event.preventDefault(); setLoading(true); try { const result = await api<{ authorizationUrl: string }>("/api/wallet/fund", { method: "POST", body: JSON.stringify({ amountMinor: Math.round(Number(amount) * 100) }) }); window.location.assign(result.authorizationUrl); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to initialize payment"); setLoading(false); } }
  return <><PageHeader eyebrow="Digital wallet" title="Your wallet" copy="Fund securely through Paystack and review every credit and debit." /><section className="wallet-grid"><div className="premium-wallet"><div className="flex items-start justify-between"><div><p>Available balance</p><h2>{money(balance)}</h2></div><WalletCards /></div><div className="mt-auto flex items-end justify-between"><div><small>ACCOUNT HOLDER</small><b>{auth.currentUser?.displayName || "DMB user"}</b></div><span>•••• {auth.currentUser?.uid.slice(-4).toUpperCase() || "0000"}</span></div></div><form onSubmit={fund} className="ui-card p-5 sm:p-6"><p className="ui-eyebrow">Fund wallet</p><h2 className="mt-2 text-xl font-black">Add money securely</h2><p className="mt-2 text-xs text-[var(--muted)]">You&apos;ll continue to Paystack to authorize payment.</p><label className="ui-label mt-6">Amount<div className="wallet-amount-input"><span>₦</span><input required min="100" type="number" value={amount} onChange={event => setAmount(event.target.value)} placeholder="0.00" /></div></label><div className="amount-options mt-3">{[2000, 5000, 10000, 20000].map(value => <button type="button" key={value} onClick={() => setAmount(String(value))} className={amount === String(value) ? "is-selected" : ""}>₦{value.toLocaleString()}</button>)}</div><button disabled={loading} className="ui-button-primary mt-5 w-full">{loading ? <LoaderCircle className="animate-spin" size={16} /> : <CreditCard size={16} />} Continue to Paystack</button></form></section><div className="mt-5"><TransactionsTable kind="all" /></div></>;
}

function ServicesWorkspace() {
  const items = [{ title: "Digital marketplace", copy: "Preview numbers, creative assets, templates, and approved digital products.", href: "/dashboard/marketplace", icon: Store }, { title: "SMS verification", copy: "Rent provider-supported numbers and receive real messages.", href: "/dashboard/sms", icon: MessageSquareText }, { title: "Airtime recharge", copy: "Top up MTN, Airtel, Glo and 9mobile numbers.", href: "/dashboard/airtime", icon: PhoneCall }, { title: "Mobile data", copy: "Browse live network bundles and complete checkout.", href: "/dashboard/data", icon: Wifi }, { title: "Electricity bills", copy: "Validate meters and pay supported Nigerian DISCOs.", href: "/dashboard/electricity", icon: Bolt }, { title: "Wallet funding", copy: "Add money securely using Paystack verification.", href: "/dashboard/wallet", icon: WalletCards }];
  return <><PageHeader eyebrow="Service centre" title="Everything in one place" copy="Choose a service and complete it through a focused, secure flow." /><div className="services-gallery">{items.map(({ title, copy, href, icon: Icon }, index) => <Link href={href} key={title} className="service-gallery-card"><span className={index % 2 ? "rose" : "blue"}><Icon size={22} /></span><div><h2>{title}</h2><p>{copy}</p></div><ChevronRight size={18} /></Link>)}</div></>;
}

function ProfileOrSupport({ type }: { type: "profile" | "support" }) {
  const support = type === "support";
  return <><PageHeader eyebrow={support ? "Help centre" : "Account settings"} title={support ? "How can we help?" : "Profile & security"} copy={support ? "Tell us what happened and include a transaction reference when available." : "Keep your personal details and account security current."} /><div className="grid items-start gap-5 xl:grid-cols-[1fr_320px]"><section className="ui-card p-5 sm:p-7"><div className="workspace-card-title"><span>{support ? <LifeBuoy size={16} /> : <UserRound size={16} />}</span><div><h2>{support ? "Submit a support request" : "Personal information"}</h2><p>{support ? "Our team will use these details to investigate." : "Details connected to your Firebase account."}</p></div></div><div className="mt-6 grid gap-5 sm:grid-cols-2"><label className="ui-label">{support ? "Subject" : "Full name"}<input className="ui-input" defaultValue={support ? "" : auth.currentUser?.displayName || ""} placeholder={support ? "What can we help with?" : "Your full name"} /></label><label className="ui-label">{support ? "Transaction reference (optional)" : "Email address"}<input className="ui-input" defaultValue={support ? "" : auth.currentUser?.email || ""} disabled={!support} placeholder={support ? "NVR-..." : "you@example.com"} /></label></div>{support && <label className="ui-label mt-5">Message<textarea className="ui-input min-h-36" placeholder="Describe the issue in detail…" /></label>} {!support && <label className="ui-label mt-5">Phone number<input className="ui-input" placeholder="080 0000 0000" /></label>}<button onClick={() => toast.success(support ? "Support form is ready for backend ticket integration." : "Profile form is ready for Firestore profile updates.")} className="ui-button-primary mt-6">{support ? <Send size={15} /> : <ShieldCheck size={15} />}{support ? "Submit request" : "Save changes"}</button></section><aside className="space-y-4"><div className="ui-card p-5"><span className="dash-icon-blue"><ShieldCheck size={18} /></span><h3 className="mt-5 text-sm font-black">Account security</h3><p className="mt-2 text-xs leading-5 text-[var(--muted)]">Authentication is protected by Firebase and server-verified session tokens.</p></div><div className="ui-card p-5"><span className="dash-icon-blue"><Mail size={18} /></span><h3 className="mt-5 text-sm font-black">Email support</h3><p className="mt-2 text-xs leading-5 text-[var(--muted)]">Include the exact transaction reference for faster investigation.</p></div></aside></div></>;
}

export function CustomerWorkspace({ section = "services" }: { section?: string }) {
  if (section === "sms") return <SmsWorkspace />;
  if (section === "airtime" || section === "data" || section === "electricity") return <VtuWorkspace type={section} />;
  if (section === "wallet") return <WalletWorkspace />;
  if (section === "transactions") return <><PageHeader eyebrow="Account activity" title="Transactions" copy="Every wallet credit, purchase, provider outcome, and refund in one searchable ledger." /><TransactionsTable kind="all" /></>;
  if (section === "notifications") return <><PageHeader eyebrow="Notification centre" title="Updates that matter" copy="Payment confirmations, service updates, and security notices will appear here." /><section className="ui-card"><EmptyState icon={Bell} title="You're all caught up" copy="There are no new notifications for your account." /></section></>;
  if (section === "profile" || section === "support") return <ProfileOrSupport type={section} />;
  return <ServicesWorkspace />;
}
